css:
:root{--k:#080808;--k2:#111111;--w:#F7F7F5;--g:#F3F4F6;--l:#C7FF3F;--ink:#1a1a1a;--mute:#5f6368;--line:#e2e3e0;--dline:#26262a;--dmute:#a1a1a6;--err:#b3261e;box-sizing:border-box;padding-top:env(safe-area-inset-top,0px);padding-bottom:env(safe-area-inset-bottom,0px);color-scheme:light}
html{scroll-behavior:smooth;scroll-padding-top:90px}
*,*::before,*::after{box-sizing:inherit}
[hidden]{display:none!important}
body{margin:0;font:400 16px/1.6 Inter,system-ui,sans-serif;color:var(--ink);background:var(--w);-webkit-font-smoothing:antialiased;overflow-x:clip}
h1,h2,h3,h4,h5{font-family:Sora,Manrope,sans-serif;margin:0;line-height:1.1;letter-spacing:-.025em}
p{margin:0}a{color:inherit;text-decoration:none}ol,ul{margin:0;padding:0;list-style:none}
:focus-visible{outline:2px solid var(--l);outline-offset:3px;box-shadow:0 0 0 4px var(--k)}
.wrap{max-width:1200px;margin:0 auto;padding:0 24px;position:relative;z-index:1}
section{padding:96px 0;position:relative}
.dk{background:var(--k);color:#fff}.lt{background:var(--w);color:var(--ink)}.gr{background:var(--g);color:var(--ink)}
.dk p{color:var(--dmute)}.lt p,.gr p{color:var(--mute)}
.btn{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:14px 24px;min-height:52px;border-radius:999px;font:600 15px Inter;border:1.5px solid transparent;cursor:pointer;transition:transform .15s,background .15s}
.btn:hover{transform:translateY(-2px)}.btn.xl{padding:18px 32px;font-size:17px}
.b-l{background:var(--l);color:var(--k)}.b-d{background:var(--k);color:#fff}.b-o{border-color:#ffffff40;color:#fff}.b-o:hover{background:#ffffff14}
.eb{display:inline-flex;align-items:center;gap:10px;font:600 13px Inter;letter-spacing:.08em;margin-bottom:22px}
.eb::before{content:"";width:8px;height:8px;border-radius:50%;background:var(--l)}
.dk .eb{color:var(--l)}.lt .eb,.gr .eb{color:var(--ink)}.lt .eb::before,.gr .eb::before{background:var(--k)}
.h2{font-size:clamp(30px,4.4vw,56px);letter-spacing:-.035em;line-height:1.05}
nav{position:sticky;top:0;z-index:30;background:#080808f2;color:#fff;border-bottom:1px solid var(--dline)}
nav .wrap{display:flex;align-items:center;justify-content:space-between;height:68px}
.logo{font:700 21px Sora;letter-spacing:-.03em}.logo i{font-style:normal;color:var(--l)}
nav ul{display:flex;gap:30px;font-size:14.5px;color:#d0d0d4}nav ul a:hover{color:var(--l)}nav .btn{padding:10px 18px;font-size:14px;min-height:0}
/* motion */
.js .rv{opacity:0;transform:translateY(26px);transition:opacity .7s ease,transform .7s ease;transition-delay:var(--d,0s)}
.js .rv.in{opacity:1;transform:none}
.mk{display:block;overflow:hidden;padding-bottom:.1em;margin-bottom:-.1em}.mk>span{display:block}
.js .mk>span{transform:translateY(110%);transition:transform .9s cubic-bezier(.2,.7,.2,1);transition-delay:var(--d,0s)}
.js .in .mk>span,.js .mk.in>span{transform:none}
/* hero */
.hero{padding:88px 0 150px;background:radial-gradient(circle at 88% 0,#C7FF3F12,transparent 45%),var(--k)}
.hero h1{font-size:clamp(36px,6vw,80px);line-height:1.01;letter-spacing:-.045em;max-width:900px}.hero h1 .m{color:var(--l)}
.hero .sub{margin-top:26px;font-size:clamp(17px,2vw,20px);max-width:600px;color:#d6d6da}
/* form */
.fs{padding:0 0 96px;margin-top:-86px}
.card{background:#fff;border:1px solid var(--line);border-radius:28px;box-shadow:0 30px 70px #00000014;padding:40px;max-width:900px;margin:0 auto}
.prog{margin-bottom:34px}.prog .t{display:flex;justify-content:space-between;font:600 13px Inter;color:var(--mute);margin-bottom:12px}.prog .t b{color:var(--ink)}
.bars{display:grid;grid-template-columns:repeat(4,1fr);gap:8px}.bars i{height:5px;border-radius:3px;background:var(--line);transition:background .3s}.bars i.on{background:var(--k)}.bars i.cur{background:var(--l);box-shadow:inset 0 0 0 1px var(--k)}
.stp{border:0;margin:0;padding:0;min-width:0}
.stp h2{font-size:clamp(24px,3vw,34px);letter-spacing:-.03em;margin-bottom:8px;outline:0}
.stp .hint{font-size:15px;margin-bottom:24px}
.opts{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}
.opts.sm{grid-template-columns:repeat(auto-fill,minmax(150px,1fr))}.opts.pl{grid-template-columns:repeat(auto-fill,minmax(210px,1fr))}
.o{position:relative;display:block}
.o input{position:absolute;opacity:0;inset:0;width:100%;height:100%;margin:0;cursor:pointer}
.o span{display:flex;flex-direction:column;justify-content:center;gap:4px;min-height:68px;padding:16px 18px;border:1.5px solid var(--line);border-radius:16px;background:#fff;transition:border-color .15s,background .15s,transform .15s}
.o b{font:600 16px Sora;letter-spacing:-.02em}.o small{font-size:13.5px;color:var(--mute);line-height:1.4}
.o:hover span{border-color:#9a9c98}
.o input:checked+span{background:var(--k);border-color:var(--k);color:#fff}.o input:checked+span small{color:var(--dmute)}
.o input:checked+span b::after{content:" ✓";color:var(--l)}
.o input:focus-visible+span{outline:2px solid var(--k);outline-offset:3px}
.opts.pl .o span{min-height:56px;padding:12px 16px}.opts.pl .o b{font:600 15px Inter}
.grp{margin-top:30px}.grp h3{font:600 15px Sora;margin-bottom:12px}.grp .note{font-size:13.5px;margin:-4px 0 12px}
.fld{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.f{display:flex;flex-direction:column;gap:7px;min-width:0}.f.full{grid-column:1/-1}
.f label{font:600 14px Inter}.f label em{font-style:normal;color:var(--mute);font-weight:400}.f label i{font-style:normal;color:var(--ink)}
.f .help{font-size:13.5px;color:var(--mute)}
.f input,.f textarea{width:100%;font:400 16px Inter;color:var(--ink);padding:14px 16px;min-height:54px;border:1.5px solid #c9cac6;border-radius:14px;background:#fff;transition:border-color .15s}
.f textarea{min-height:140px;resize:vertical}
.f input:hover,.f textarea:hover{border-color:#8a8c88}
.f input:focus,.f textarea:focus{outline:2px solid var(--k);outline-offset:2px;border-color:var(--k)}
.f .inv{border-color:var(--err)!important;background:#fff7f6}
.err{display:none;gap:8px;align-items:flex-start;font-size:14px;font-weight:500;color:var(--err);line-height:1.4}
.err::before{content:"✕";font-weight:700;flex:none}.err.show{display:flex}
.fm{display:none;margin-top:22px;padding:14px 16px;border:1.5px solid var(--err);border-radius:14px;background:#fff7f6;color:var(--err);font-size:14.5px;font-weight:500}.fm.show{display:block}
.acts{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-top:34px;padding-top:24px;border-top:1px solid var(--line)}
.back{font:600 15px Inter;background:none;border:0;color:var(--mute);cursor:pointer;padding:14px 4px;min-height:52px}.back:hover{color:var(--ink)}
.hp{position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden}
.dn{text-align:left}.dn h2{font-size:clamp(32px,5vw,56px);letter-spacing:-.04em;line-height:1.02;margin-bottom:16px;outline:0}
.dn .ok{width:56px;height:56px;border-radius:50%;background:var(--l);display:grid;place-items:center;font:700 26px Inter;margin-bottom:26px;border:2px solid var(--k)}
.dn>p{font-size:17px;max-width:520px;margin-bottom:26px}
.sm2{border-top:1px solid var(--line);margin-bottom:28px}.sm2 div{display:flex;justify-content:space-between;gap:20px;padding:12px 0;border-bottom:1px solid var(--line);font-size:15px}.sm2 span{color:var(--mute)}.sm2 b{text-align:right;font-weight:600}
.dn .ctas{display:flex;flex-wrap:wrap;gap:12px;align-items:center}.dn .tl{font:600 15px Inter;border-bottom:2px solid var(--l);padding-bottom:2px}
.dm{margin-top:22px;font-size:13.5px;color:var(--mute);border:1px dashed #c9cac6;border-radius:12px;padding:10px 14px}
/* alt contact */
.alt .wrap{display:grid;grid-template-columns:1.1fr 1fr;gap:56px;align-items:center}
.alt h2{font-size:clamp(32px,4.8vw,64px);letter-spacing:-.04em;line-height:1.02}
.alt .ct{display:flex;flex-direction:column;gap:12px;align-items:flex-start}
.alt .ct p{margin-bottom:6px;font-size:17px}
.alt .ph{border:1.5px dashed #3a3a40;border-radius:16px;padding:18px 20px;font-size:14.5px;color:var(--dmute);max-width:420px}
/* faq */
.fq{max-width:800px;margin-top:40px}
details{border-top:1px solid var(--line);padding:22px 0}details:last-child{border-bottom:1px solid var(--line)}
summary{cursor:pointer;font:600 18px Sora;list-style:none;display:flex;justify-content:space-between;gap:16px;min-height:28px}
summary::-webkit-details-marker{display:none}summary::after{content:"+";font-size:26px;line-height:1;transition:transform .2s;flex:none}
details[open] summary::after{transform:rotate(45deg)}
details p{margin-top:12px;color:var(--mute);max-width:660px}
/* final visual */
.fv{padding:80px 0;overflow:hidden}
.fv .t{font:700 clamp(46px,13vw,190px)/.95 Sora;letter-spacing:-.055em;color:transparent;-webkit-text-stroke:1.5px #cfd1cc;user-select:none}
.fv .t span{display:block}.fv .t span:nth-child(3){-webkit-text-stroke-color:var(--k)}
footer{background:var(--k);color:#fff;padding:72px 0 32px}
.fg{display:grid;grid-template-columns:1.6fr repeat(4,1fr);gap:36px}
footer p,footer li,footer a{color:var(--dmute);font-size:14.5px}footer h4{font-size:14px;margin-bottom:14px}footer li{padding:5px 0}footer a:hover{color:var(--l)}
.fb{margin-top:48px;padding-top:24px;border-top:1px solid var(--dline);display:flex;justify-content:space-between;flex-wrap:wrap;gap:12px;font-size:13.5px;color:var(--dmute)}
.bgw{font:700 clamp(40px,12vw,150px)/1 Sora;letter-spacing:-.05em;color:#161618;margin-top:40px;white-space:nowrap;overflow:hidden}
/* tablet */
@media(max-width:1020px){
.opts{grid-template-columns:repeat(2,minmax(0,1fr))}.alt .wrap{grid-template-columns:1fr;gap:32px}.fg{grid-template-columns:1fr 1fr 1fr}}
@media(max-width:860px){nav ul{display:none}}
/* mobile */
@media(max-width:600px){
section{padding:68px 0}.wrap{padding:0 20px}.hero{padding:60px 0 120px}.fs{margin-top:-70px;padding-bottom:68px}
.card{padding:22px 18px;border-radius:22px}.opts,.opts.sm,.opts.pl{grid-template-columns:1fr}.opts.sm{grid-template-columns:1fr 1fr}
.fld{grid-template-columns:1fr}.prog .t span:last-child{display:none}
.acts{position:sticky;bottom:0;background:#fff;margin:26px -18px -22px;padding:14px 18px calc(14px + env(safe-area-inset-bottom,0px));border-radius:0 0 22px 22px;box-shadow:0 -10px 20px #0000000a}
.acts .btn{flex:1}.dn .ctas .btn{width:100%}.alt .btn,.cta .btn{width:100%}.sm2 div{flex-direction:column;gap:2px}.sm2 b{text-align:left}
.fv{padding:56px 0}.fg{grid-template-columns:1fr 1fr}.fg>div:first-child{grid-column:span 2}}
@media(prefers-reduced-motion:reduce){*{transition:none!important;animation:none!important;scroll-behavior:auto!important}.js .rv,.js .mk>span{opacity:1;transform:none}}

