(function(){
/* ============ SITE OWNER CONFIG: edit this block ============ */
var CONFIG={
  whatsapp:'',   // digits only with country code, e.g. '919876543210'. Leave '' to hide.
  email:'',      // e.g. 'hello@yourdomain.in'. Leave '' to hide.
  endpoint:'/api/contact',   // URL that receives the brief (POST, JSON). Leave '' for demo mode.
  demo:false      // shows a "demo mode" note on the success state. Set false at launch.
};
var SERVICES=[
 {v:'Website Development',d:'Business sites, stores and web apps'},
 {v:'App Development',d:'Android, iOS and cross-platform'},
 {v:'AI & Automation',d:'Assistants, workflows and integrations'},
 {v:'Digital Marketing',d:'SEO, ads and lead generation'},
 {v:'Multiple Services',d:'A mix of the above'},
 {v:'Not Sure Yet',d:'Help me work it out'}];
var TYPES=['Small Business','Startup','Hotel / Hospitality','Restaurant','Gym / Fitness','Real Estate','Clinic','E-commerce','Corporate','Other'];
var BUDGETS=['Exploring / Need Guidance','Under ₹50,000','₹50,000 – ₹1,00,000','₹1,00,000 – ₹2,50,000','₹2,50,000 – ₹5,00,000','₹5,00,000+','Enterprise / Let’s Discuss']; // editable ranges
var TIMES=['Exploring','As Soon As Practical','Within 1 Month','1–3 Months','3+ Months'];
var PREFS=['Email','Phone','WhatsApp','Video Call'];
/* ============================================================ */

var $=function(s,c){return(c||document).querySelector(s)};
function opt(name,val,desc,idx){var id=name+idx;return '<label class="o"><input type="radio" name="'+name+'" id="'+id+'" value="'+val.replace(/"/g,'&quot;')+'"><span><b>'+val.replace(/&/g,'&amp;')+'</b>'+(desc?'<small>'+desc+'</small>':'')+'</span></label>';}
function fill(id,name,arr,desc){$('#'+id).innerHTML=arr.map(function(a,i){return desc?opt(name,a.v,a.d,i):opt(name,a,'',i);}).join('');}
fill('o-service','service',SERVICES,true);fill('o-type','type',TYPES);fill('o-budget','budget',BUDGETS);fill('o-time','timeline',TIMES);fill('o-contact','contact',PREFS);

var STEPS=['What can we help with?','Who are you?','About the project','Last details'];
var step=1,reduce=window.matchMedia('(prefers-reduced-motion: reduce)').matches;
var f=$('#f'),next=$('#next'),back=$('#back'),fm=$('#fm');

function setErr(id,msg,inputEl){var e=$('#'+id);e.textContent=msg||'';e.classList.toggle('show',!!msg);if(inputEl){inputEl.classList.toggle('inv',!!msg);inputEl.setAttribute('aria-invalid',msg?'true':'false');}}
function val(n){return(f.elements[n].value||'').trim();}
function checked(n){var c=f.querySelector('input[name="'+n+'"]:checked');return c?c.value:'';}
var rules={
 name:function(){return val('name').length<2?'Please enter your name.':'';},
 email:function(){return /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(val('email'))?'':'Please enter a valid email address, like name@business.in.';},
 phone:function(){var d=val('phone').replace(/[^\d]/g,'');return d.length>=10&&d.length<=15&&/^[+\d][\d\s\-()]*$/.test(val('phone'))?'':'Please enter a valid phone or WhatsApp number (at least 10 digits).';},
 site:function(){var v=val('website');return !v||/^(https?:\/\/)?([\w-]+\.)+[a-z]{2,}(\/.*)?$/i.test(v)?'':'That doesn’t look like a website address. You can leave it blank.';},
 desc:function(){return val('description').length<10?'Please tell us a little about the project (at least 10 characters).':'';}
};
var map={name:'name',email:'email',phone:'phone',site:'site',desc:'desc'};
function check(k){var el=$('#'+k),m=rules[k]();setErr('e-'+k,m,el);return !m;}
function validate(n){
 var ok=true,first=null;
 if(n===1){var m=checked('service')?'':'Please choose what we can help with.';setErr('e-service',m);if(m){ok=false;first=$('#o-service input');}}
 if(n===2){var m2=checked('type')?'':'Please choose what describes you best.';setErr('e-type',m2);if(m2){ok=false;first=$('#o-type input');}}
 if(n===3){['name','email','phone','site','desc'].forEach(function(k){if(!check(k)){ok=false;if(!first)first=$('#'+k);}});}
 var c=n===3?document.querySelectorAll('#s3 .err.show').length:(ok?0:1);
 fm.classList.toggle('show',!ok);fm.textContent=ok?'':(c>1?'Please fix the '+c+' highlighted fields to continue.':'Please fix the highlighted field to continue.');
 if(!ok&&first)first.focus();
 return ok;
}
/* persistent validation: once a field is invalid, re-check live; check on blur */
['name','email','phone','site','desc'].forEach(function(k){var el=$('#'+k);
 el.addEventListener('blur',function(){if(el.value||el.classList.contains('inv')||k==='name'&&false)check(k);});
 el.addEventListener('input',function(){if(el.classList.contains('inv')){check(k);if(!document.querySelectorAll('#s3 .err.show').length)fm.classList.remove('show');}});});
f.addEventListener('change',function(e){if(e.target.name==='service'){setErr('e-service','');fm.classList.remove('show');}if(e.target.name==='type'){setErr('e-type','');fm.classList.remove('show');}});

function show(n,focus){
 step=n;
 for(var i=1;i<=4;i++){$('#s'+i).hidden=(i!==n);}
 $('#sn').textContent=n;$('#sl').textContent=STEPS[n-1];
 [].forEach.call($('#bars').children,function(b,i){b.className=i+1<n?'on':(i+1===n?'cur':'');});
 back.hidden=n===1;next.textContent=n===4?'Send Project Brief →':'Continue →';
 fm.classList.remove('show');
 if(focus){var h=$('#s'+n+' h2');$('.prog').scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'});setTimeout(function(){h.focus({preventScroll:true});},reduce?0:350);}
}
back.addEventListener('click',function(){if(step>1)show(step-1,true);});
f.addEventListener('submit',function(e){
 e.preventDefault();
 if(!validate(step))return;
 if(step<4){show(step+1,true);return;}
 if(val('company_site'))return; /* honeypot */
 submit();
});
function data(){return{service:checked('service'),type:checked('type'),name:val('name'),business:val('business'),email:val('email'),phone:val('phone'),website:val('website'),description:val('description'),budget:checked('budget'),timeline:checked('timeline'),contact:checked('contact')};}
function done(d){
 var rows=[['Help with',d.service],['You are',d.type],['Budget',d.budget],['Timeline',d.timeline],['Preferred contact',d.contact]].filter(function(r){return r[1];});
 $('#sum').innerHTML=rows.map(function(r){return '<div><span>'+r[0]+'</span><b></b></div>';}).join('');
 [].forEach.call($('#sum').querySelectorAll('b'),function(b,i){b.textContent=rows[i][1];});
 $('#flow').hidden=true;$('#done').hidden=false;$('#demo').hidden=!(CONFIG.demo&&!CONFIG.endpoint);
 $('#done').scrollIntoView({behavior:reduce?'auto':'smooth',block:'start'});setTimeout(function(){$('#dh').focus({preventScroll:true});},reduce?0:350);
}
function submit(){
 var d=data();
 if(!CONFIG.endpoint){done(d);return;}
 next.disabled=true;next.textContent='Sending…';
 fetch(CONFIG.endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)})
 .then(function(r){if(!r.ok)throw 0;done(d);})
 .catch(function(){next.disabled=false;next.textContent='Send Project Brief →';fm.textContent='Something went wrong and your brief wasn’t sent. Please try again, or use WhatsApp or email below.';fm.classList.add('show');});
}
$('#again').addEventListener('click',function(){f.reset();[].forEach.call(f.querySelectorAll('.inv'),function(x){x.classList.remove('inv')});[].forEach.call(document.querySelectorAll('.err'),function(x){x.classList.remove('show')});$('#done').hidden=true;$('#flow').hidden=false;next.disabled=false;show(1,true);});

/* contact info: only render what is configured */
(function(){
 var alt=$('#alt'),fc=$('#fc'),html='',fl='';
 if(CONFIG.whatsapp){var w='https://wa.me/'+CONFIG.whatsapp.replace(/\D/g,'');html+='<a class="btn b-l xl" href="'+w+'" rel="noopener">Chat on WhatsApp →</a>';fl+='<li><a href="'+w+'">WhatsApp</a></li>';}
 if(CONFIG.email){html+='<a class="btn b-o xl" href="mailto:'+CONFIG.email+'">Email Us →</a>';fl+='<li><a href="mailto:'+CONFIG.email+'">'+CONFIG.email+'</a></li>';}
 if(html)alt.insertAdjacentHTML('beforeend',html);
 else alt.insertAdjacentHTML('beforeend','<div class="ph">Direct contact options will appear here once a WhatsApp number or email is configured.</div>');
 if(fl)fc.innerHTML=fl+'<li>India</li>';
})();

show(1,false);

var els=document.querySelectorAll('.rv');
if(!('IntersectionObserver' in window)||reduce){els.forEach(function(e){e.classList.add('in')});}
else{var io=new IntersectionObserver(function(es){es.forEach(function(e){if(e.isIntersecting){e.target.classList.add('in');io.unobserve(e.target);}});},{threshold:.12,rootMargin:'0px 0px -6% 0px'});els.forEach(function(e){io.observe(e)});}
})();
